import org.bukkit.*;
import org.bukkit.command.*;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.*;
import org.bukkit.event.*;
import org.bukkit.event.block.*;
import org.bukkit.event.entity.*;
import org.bukkit.event.player.*;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.plugin.java.JavaPlugin;
import java.io.File;
import java.util.*;
public class PrisonEvo extends JavaPlugin implements Listener {
 World w; File f; YamlConfiguration data; Random rng=new Random();
 Material[][] ores={{Material.STONE,Material.COAL_ORE,Material.IRON_ORE},{Material.STONE,Material.COPPER_ORE,Material.GOLD_ORE},{Material.DEEPSLATE,Material.LAPIS_ORE,Material.DIAMOND_ORE},{Material.NETHERRACK,Material.NETHER_GOLD_ORE,Material.EMERALD_ORE},{Material.DEEPSLATE,Material.DIAMOND_ORE,Material.ANCIENT_DEBRIS}}; String[] zones={"Карьер","Медные тоннели","Кристальные пещеры","Магма","Бездна"};
 String path(Player p,String k){return p.getUniqueId()+"."+k;} int val(Player p,String k){return data.getInt(path(p,k));} void set(Player p,String k,int n){data.set(path(p,k),n);} int rank(Player p){return Math.max(1,val(p,"rank"));} void msg(Player p,String s){p.sendMessage("§d§lHYLOR §8» §f"+s);} void save(){try{data.save(f);}catch(Exception e){getLogger().warning(e.toString());}}
 public void onEnable(){getDataFolder().mkdirs(); f=new File(getDataFolder(),"players.yml");data=YamlConfiguration.loadConfiguration(f);w=Bukkit.getWorlds().get(0);getServer().getPluginManager().registerEvents(this,this);Bukkit.getScheduler().runTask(this,()->{if(!getConfig().getBoolean("built")){build();getConfig().set("built",true);saveConfig();}});Bukkit.getScheduler().runTaskTimer(this,()->{for(Player p:Bukkit.getOnlinePlayers()){int n=val(p,"auto");if(n>0)set(p,"storage",Math.min(1000+n*500,val(p,"storage")+n*4));}save();},1200,1200);}
 public void onDisable(){save();} Material ore(int n){int x=rng.nextInt(100);return ores[n][x<55?0:x<85?1:2];} void put(int x,int y,int z,Material m){w.getBlockAt(x,y,z).setType(m,false);}
 void build(){for(int x=-18;x<=18;x++)for(int z=-18;z<=18;z++)put(x,100,z,Math.abs(x)==18||Math.abs(z)==18?Material.PINK_CONCRETE:((x+z)%7==0?Material.PINK_TERRACOTTA:Material.POLISHED_DEEPSLATE));w.setSpawnLocation(new Location(w,.5,101,.5));for(int i=0;i<5;i++){int cx=i*32-64;for(int x=cx-10;x<=cx+10;x++)for(int z=30;z<=50;z++){put(x,95,z,Material.BEDROCK);for(int y=96;y<=100;y++)put(x,y,z,x==cx-10||x==cx+10||z==30||z==50?Material.POLISHED_BLACKSTONE:ore(i));}}npc(-6,"§dШАХТЫ", "mines");npc(-2,"§6МАГАЗИН", "shop");npc(2,"§bАВТОШАХТА", "auto");npc(6,"§eЗАДАНИЯ", "quest");}
 void npc(int x,String name,String tag){Villager v=(Villager)w.spawnEntity(new Location(w,x+.5,101,-4.5),EntityType.VILLAGER);v.setAI(false);v.setInvulnerable(true);v.setCustomName(name);v.setCustomNameVisible(true);v.addScoreboardTag("hylor_"+tag);}
 ItemStack item(Material m,String title,String... lore){ItemStack i=new ItemStack(m);ItemMeta a=i.getItemMeta();a.setDisplayName(title);a.setLore(Arrays.asList(lore));i.setItemMeta(a);return i;}
 void menu(Player p,String type){Inventory inv=Bukkit.createInventory(null,27,"§5HYLOR §8| §d"+type);switch(type){case "Шахты":for(int i=0;i<5;i++)inv.setItem(10+i,item(ores[i][2],"§d"+zones[i],"§7Ранг: "+(i*5+1)));break;case "Магазин":inv.setItem(10,item(Material.EMERALD,"§aПродать ресурсы"));inv.setItem(12,item(Material.IRON_PICKAXE,"§fЖелезная кирка §e500"));inv.setItem(13,item(Material.DIAMOND_PICKAXE,"§bАлмазная кирка §e2500"));inv.setItem(14,item(Material.NETHERITE_PICKAXE,"§dНезеритовая кирка §e10000"));inv.setItem(16,item(Material.EXPERIENCE_BOTTLE,"§eПовысить ранг","§7Цена: "+rank(p)*300));break;case "Автошахта":inv.setItem(11,item(Material.HOPPER,"§bУлучшить","§7Уровень: "+val(p,"auto"),"§7Цена: "+(val(p,"auto")+1)*1500,"§7Работает пока вы в сети"));inv.setItem(15,item(Material.CHEST,"§aЗабрать прибыль","§7Монет: "+val(p,"storage")));break;default:inv.setItem(13,item(Material.PAPER,"§eЗадание: добыть 100 блоков","§7Прогресс: "+val(p,"quest")+"/100","§7Награда: 1000 монет"));}p.openInventory(inv);}
 boolean pay(Player p,int n){if(val(p,"money")<n){msg(p,"§cНужно монет: "+n);return false;}set(p,"money",val(p,"money")-n);return true;}
 @EventHandler public void click(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p))return;String t=ChatColor.stripColor(e.getView().getTitle());if(!t.startsWith("HYLOR | "))return;e.setCancelled(true);if(e.getClickedInventory()!=e.getView().getTopInventory())return;int s=e.getRawSlot();if(t.endsWith("Шахты")&&s>=10&&s<=14){int i=s-10;if(rank(p)<i*5+1){msg(p,"§cНужен ранг "+(i*5+1));return;}p.teleport(new Location(w,i*32-63.5,101,40.5));p.closeInventory();}else if(t.endsWith("Магазин")){if(s==10)sell(p);if(s>=12&&s<=14){int[] price={500,2500,10000};Material[] pick={Material.IRON_PICKAXE,Material.DIAMOND_PICKAXE,Material.NETHERITE_PICKAXE};if(p.getInventory().firstEmpty()<0){msg(p,"§cИнвентарь заполнен");return;}if(pay(p,price[s-12])){p.getInventory().addItem(new ItemStack(pick[s-12]));msg(p,"§aКирка куплена");}}if(s==16){if(rank(p)<25&&pay(p,rank(p)*300)){set(p,"rank",rank(p)+1);msg(p,"§aРанг: "+rank(p));}}}else if(t.endsWith("Автошахта")){if(s==11){int n=val(p,"auto");if(rank(p)<5){msg(p,"§cДоступно с 5 ранга");return;}if(n<20&&pay(p,(n+1)*1500)){set(p,"auto",n+1);msg(p,"§aУровень: "+(n+1));}}if(s==15){int n=val(p,"storage");set(p,"storage",0);set(p,"money",val(p,"money")+n);msg(p,"§aПолучено: "+n);}}else if(t.endsWith("Задания")&&s==13&&val(p,"quest")>=100){set(p,"quest",0);set(p,"money",val(p,"money")+1000);msg(p,"§aНаграда: 1000 монет");}}
 void sell(Player p){int total=0;for(ItemStack i:p.getInventory().getContents()){if(i==null)continue;int n=switch(i.getType()){case COBBLESTONE,COBBLED_DEEPSLATE,NETHERRACK->1;case COAL,RAW_IRON,RAW_COPPER->3;case RAW_GOLD,LAPIS_LAZULI,GOLD_NUGGET->6;case DIAMOND,EMERALD,ANCIENT_DEBRIS->20;default->0;};if(n>0){total+=n*i.getAmount();i.setAmount(0);}}set(p,"money",val(p,"money")+total);msg(p,"§aПродано на "+total+" монет. Баланс: "+val(p,"money"));}
 @EventHandler public void join(PlayerJoinEvent e){Player p=e.getPlayer();if(!data.contains(path(p,"rank"))){set(p,"rank",1);p.getInventory().addItem(new ItemStack(Material.STONE_PICKAXE));p.teleport(w.getSpawnLocation());}msg(p,"§d/mines §7• §d/shop §7• §d/auto §7• §d/quest §7• §d/spawn");}
 @EventHandler public void npcClick(PlayerInteractEntityEvent e){for(String tag:e.getRightClicked().getScoreboardTags())if(tag.startsWith("hylor_")){e.setCancelled(true);menu(e.getPlayer(),switch(tag.substring(6)){case "mines"->"Шахты";case "shop"->"Магазин";case "auto"->"Автошахта";default->"Задания";});}}
 @EventHandler public void mine(BlockBreakEvent e){var b=e.getBlock();int i=-1;for(int j=0;j<5;j++)if(b.getWorld().equals(w)&&Math.abs(b.getX()-(j*32-64))<10&&b.getZ()>30&&b.getZ()<50&&b.getY()>=96&&b.getY()<=100)i=j;if(i<0||rank(e.getPlayer())<i*5+1){e.setCancelled(true);return;}Player p=e.getPlayer();set(p,"quest",Math.min(100,val(p,"quest")+1));int n=i;Bukkit.getScheduler().runTaskLater(this,()->{if(b.getType().isAir())b.setType(ore(n),false);},200);}
 @EventHandler public void place(BlockPlaceEvent e){e.setCancelled(true);}
 @EventHandler public void hurt(EntityDamageEvent e){if(e.getEntity() instanceof Player)e.setCancelled(true);}
 @EventHandler public void hunger(FoodLevelChangeEvent e){e.setCancelled(true);}
 public boolean onCommand(CommandSender s,Command cmd,String l,String[] args){if(!(s instanceof Player p))return true;switch(cmd.getName()){case "spawn"->p.teleport(w.getSpawnLocation());case "mines"->menu(p,"Шахты");case "shop"->menu(p,"Магазин");case "auto"->menu(p,"Автошахта");case "quest"->menu(p,"Задания");case "sell"->sell(p);case "balance"->msg(p,"Баланс: "+val(p,"money")+" | Ранг: "+rank(p));}return true;}
}
